using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class MarinaPropAudit{static MarinaPropAudit(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("MarinaPropAudit.request"))return;File.Delete("MarinaPropAudit.request");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var lamp=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).First(f=>f.name.StartsWith("metal street props low poly.012"));var bollard=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/bollard.prefab").GetComponentInChildren<MeshFilter>();var lines=new List<string>();foreach(var f in new[]{lamp,bollard}){lines.Add("PROP "+f.name+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh)+" submeshes="+f.sharedMesh.subMeshCount+" scale="+f.transform.lossyScale);foreach(var m in f.GetComponent<MeshRenderer>().sharedMaterials)lines.Add("MAT "+m.name+" texture="+AssetDatabase.GetAssetPath(m.mainTexture));}File.WriteAllLines("FinalEnvironmentRoadReview/MarinaPropAudit.txt",lines);}}
